import { useState } from 'react';
import Button from '../components/Button';

export default function RegisterPage() {
  const [email, setEmail] = useState('');
  const [otpSent, setOtpSent] = useState(false);
  const [otp, setOtp] = useState('');
  const [confirmed, setConfirmed] = useState(false);

  return (
    <div className="mx-auto max-w-3xl space-y-8 rounded-[2rem] bg-slate-900/80 p-8 shadow-2xl shadow-slate-950/30">
      <div>
        <p className="text-sm uppercase tracking-[0.3em] text-cyan-300">Create account</p>
        <h2 className="mt-3 text-3xl font-semibold text-white">Register with Gmail and verify your learning profile.</h2>
        <p className="mt-3 text-slate-400">Simulate a secure signup experience with OTP verification and quick onboarding.</p>
      </div>
      <div className="grid gap-6 sm:grid-cols-[1fr_0.8fr]">
        <div className="space-y-4 rounded-3xl border border-slate-800 bg-slate-950/90 p-6">
          <label className="block text-sm font-medium text-slate-200">Gmail address</label>
          <input
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="you@example.com"
            className="w-full rounded-3xl border border-slate-800 bg-slate-900 px-4 py-3 text-slate-100 outline-none transition focus:border-cyan-500"
          />
          <Button
            onClick={() => setOtpSent(true)}
            disabled={!email}
            className="w-full"
          >
            Send OTP
          </Button>
          {otpSent && (
            <div className="space-y-4 rounded-3xl border border-cyan-600/30 bg-slate-900/80 p-4 text-slate-200">
              <p className="text-sm text-slate-400">OTP has been sent to your email. Enter the 6-digit code below to continue.</p>
              <input
                value={otp}
                onChange={(e) => setOtp(e.target.value)}
                placeholder="123456"
                className="w-full rounded-3xl border border-slate-800 bg-slate-900 px-4 py-3 text-slate-100 outline-none transition focus:border-cyan-500"
              />
              <Button
                onClick={() => setConfirmed(true)}
                disabled={otp.length !== 6}
                className="w-full"
              >
                Verify OTP
              </Button>
            </div>
          )}
          {confirmed && <p className="rounded-3xl bg-emerald-500/15 px-4 py-3 text-sm text-emerald-300">OTP verified successfully. Continue to create your profile.</p>}
        </div>
        <div className="rounded-3xl bg-gradient-to-br from-slate-950 via-slate-900 to-cyan-950 p-6 text-slate-200">
          <h3 className="text-lg font-semibold">Why register?</h3>
          <ul className="mt-4 space-y-3 text-sm text-slate-400">
            <li>• Personalized AI roadmap and progress tracking</li>
            <li>• Save study tasks and quiz performance</li>
            <li>• Access domain-specific learning paths</li>
          </ul>
        </div>
      </div>
    </div>
  );
}
